function decodeJwt(token) {
    try {
        var part = token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
        while (part.length % 4) { part += '='; }
        return JSON.parse(decodeURIComponent(escape(atob(part))));
    } catch (e) {
        return null;
    }
}

function captureToken(token, key) {
  if (!token) return;
  pm.collectionVariables.set(key, token);
  const payload = decodeJwt(token);
  if (!payload) return;
  if (payload.userId) pm.collectionVariables.set('userId', payload.userId);
  if (payload.role) pm.collectionVariables.set('userRole', payload.role);
  if (payload.role === 'ADMIN') pm.collectionVariables.set('adminAccessToken', token);
  if (payload.role === 'TECHNICIAN') pm.collectionVariables.set('technicianAccessToken', token);
  if (payload.role === 'CUSTOMER') pm.collectionVariables.set('customerAccessToken', token);
}

